function getResult(n, levels) {
  let ans = 0;

  for (let i = 1; i < n - 1; i++) {
    let mid = levels[i];

    let leftSmallerCount = 0;
    let leftBiggerCount = 0;

    for (let j = 0; j < i; j++) {
      if (levels[j] > mid) {
        leftBiggerCount++;
      } else {
        leftSmallerCount++;
      }
    }

    let rightSmallerCount = 0;
    let rightBiggerCount = 0;

    for (let k = i + 1; k < n; k++) {
      if (levels[k] > mid) {
        rightBiggerCount++;
      } else {
        rightSmallerCount++;
      }
    }

    ans +=
      leftBiggerCount * rightSmallerCount + leftSmallerCount * rightBiggerCount;
  }

  return ans;
}

